// The standalone entry includes the other areas; it does not depend on sibling HTML files.
export function installEmbeddedAreas(pages){
 if(location.protocol!=='file:')return;
 let frame=null,currentArea=null;
 const areaFromLink=href=>{if(!href||href.startsWith('#'))return null;const file=href.split('#')[0].split('/').at(-1),hash=href.split('#')[1]||'';if(file==='painel.html')return hash.startsWith('admin')?'admin':'seller';if(file==='vender.html')return 'vender';if(file==='index.html')return 'buyer';return null};
 function bridge(initial){window.__embeddedInitialHash=initial;document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;const href=a.getAttribute('href');if(href.startsWith('#')){e.preventDefault();e.stopImmediatePropagation();location.hash=href;document.getElementById(href.slice(1))?.scrollIntoView();return;}const file=href.split('#')[0].split('/').at(-1);if(!['index.html','painel.html','vender.html'].includes(file))return;e.preventDefault();e.stopImmediatePropagation();parent.postMessage({type:'temlogoali-area',file,hash:href.split('#')[1]||''},'*');},true);document.addEventListener('DOMContentLoaded',()=>{if(initial==='cadastro')document.querySelector('#cadastro')?.scrollIntoView();});}
 function sync(){const area=location.hash.match(/^#area\/(seller|admin|vender)$/)?.[1]||null;if(area===currentArea)return;frame?.remove();frame=null;currentArea=area;document.body.classList.toggle('embedded-area-open',!!area);const app=document.querySelector('#app');if(app)app.inert=!!area;if(!area)return;document.querySelector('#modal')?.close();frame=document.createElement('iframe');frame.className='embedded-area-frame';frame.title=area==='vender'?'Quero vender':area==='admin'?'Administração':'Central de Vendedores';const initial=area==='vender'?'cadastro':area;const script='<script>('+bridge.toString()+')('+JSON.stringify(initial)+');<\/script>';frame.srcdoc=pages[area==='vender'?'vender':'panel'].replace('</head>',script+'</head>');document.body.append(frame);}
 document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a)return;const area=areaFromLink(a.getAttribute('href'));if(!area)return;e.preventDefault();e.stopImmediatePropagation();location.hash=area==='buyer'?'#':'#area/'+area;sync();},true);
 window.addEventListener('message',e=>{if(e.source!==frame?.contentWindow||e.data?.type!=='temlogoali-area')return;const area=e.data.file==='index.html'?'buyer':e.data.file==='vender.html'?'vender':e.data.file==='painel.html'?(e.data.hash.startsWith('admin')?'admin':'seller'):null;if(!area)return;location.hash=area==='buyer'?'#':'#area/'+area;sync();});
 window.addEventListener('hashchange',sync);sync();
}

